//! Desert pyramids and jungle temples (procedural in vanilla). Layouts measured from vanilla worlds
//! generated by the official 26.2 server jar (2026-11-24, `examples/structures json|blocks|bblocks`,
//! tools/structure-sites.sh): 9 desert pyramids (seed 12345 chunks -224,-313 -238,-313 -320,-304;
//! seed 42 -86,-110 196,148 -127,-233 -116,245 -141,-235 243,147) and 12 jungle temples (seed 12345
//! -95,2 -106,11 -114,-21 -111,-56 -114,71 -147,65; seed 42 -85,180 8,-210 81,227; seed 1 4,111
//! -151,18 -154,48). A cell is the majority block of the instances (normalised into one frame) where
//! at least two instances differ from the bare terrain (Basalt's generation without structures); see
//! NOTES.md "Desert pyramids and jungle temples" for the start rules.
//!
//! Layout frame: the world frame of vanilla orientation `O` 3 (start `nextInt(4)` = 1); layers y
//! from `*_Y0` relative to the box floor, rows z, columns x (rows may be cut short); ' ' = not
//! touched (terrain stays), '.' = air.

use super::place::transform_state;
use super::template::{BBox, Rotation};
use super::{Piece, PieceKind};
use crate::random::{JavaRandom, Rng};
use crate::region::Region;
use crate::Generator;
use basalt_data::BlockState;
use std::sync::OnceLock;

/// A parsed layout in the local frame (= the world frame of `O` 0): x across the width, z along
/// the depth.
struct Layout {
    w: i32,
    d: i32,
    /// (x, y, z, state); state `u16::MAX` = random cobblestone / mossy cobblestone
    cells: Vec<(i32, i32, i32, u16)>,
    /// Placement-random draw index per cell (random cells only, else `u16::MAX`).
    draw: Vec<u16>,
    draws: usize,
}

const RANDOM: u16 = u16::MAX;

fn parse(
    layers: &[&[&str]],
    y0: i32,
    palette: &[(char, &str)],
    rows: i32,
    cols: i32,
    boxes: &[[i32; 6]],
    singles: &[(i32, i32, i32, u16)],
) -> Layout {
    let pal: Vec<(char, u16)> = palette
        .iter()
        .map(|(c, n)| {
            let s = if *n == "RANDOM_COBBLE" {
                RANDOM
            } else {
                // reference frame (O 3) -> local frame (O 0): a transpose
                let s = BlockState::parse(n).map(|b| b.0 as u16).unwrap_or(0);
                transform_state(s, Rotation::Ccw90, true)
            };
            (*c, s)
        })
        .collect();
    let mut cells = Vec::new();
    for (yi, layer) in layers.iter().enumerate() {
        for (zr, row) in layer.iter().enumerate() {
            for (xr, ch) in row.chars().enumerate() {
                if let Some((_, s)) = pal.iter().find(|p| p.0 == ch) {
                    // local x = reference z, local z = reference x
                    cells.push((zr as i32, y0 + yi as i32, xr as i32, *s));
                }
            }
        }
    }
    // vanilla's fill order (measured on the jungle temple floor: the placement random's draws
    // follow y, then local x, then local z)
    cells.sort_by_key(|c| (c.1, c.0, c.2));
    let mut index: std::collections::HashMap<(i32, i32, i32), u16> = Default::default();
    let mut n = 0u16;
    for b in boxes {
        for y in b[2]..=b[3] {
            for x in b[0]..=b[1] {
                for z in b[4]..=b[5] {
                    index.insert((x, y, z), n);
                    n += 1;
                }
            }
        }
    }
    for &(x, y, z, i) in singles {
        index.insert((x, y, z), i);
        n = n.max(i + 1);
    }
    let draw = cells
        .iter()
        .map(|c| {
            if c.3 != RANDOM {
                return u16::MAX;
            }
            *index.entry((c.0, c.1, c.2)).or_insert_with(|| {
                n += 1;
                n - 1
            })
        })
        .collect();
    Layout {
        w: rows,
        d: cols,
        cells,
        draw,
        draws: n as usize,
    }
}

fn desert() -> &'static Layout {
    static L: OnceLock<Layout> = OnceLock::new();
    L.get_or_init(|| {
        let layers: Vec<&[&str]> = DESERT_LAYERS.iter().map(|l| &l[..]).collect();
        parse(&layers, DESERT_Y0, &DESERT_PALETTE, 21, 21, &[], &[])
    })
}

fn jungle() -> &'static Layout {
    static L: OnceLock<Layout> = OnceLock::new();
    L.get_or_init(|| {
        let layers: Vec<&[&str]> = JUNGLE_LAYERS.iter().map(|l| &l[..]).collect();
        parse(
            &layers,
            JUNGLE_Y0,
            &JUNGLE_PALETTE,
            12,
            15,
            &JUNGLE_BOXES,
            &JUNGLE_DRAWS,
        )
    })
}

/// Box size (x, z) of a temple with local size (w, d) in orientation `o`.
fn box_size(o: u8, w: i32, d: i32) -> (i32, i32) {
    if o == 1 || o == 3 {
        (d, w)
    } else {
        (w, d)
    }
}

/// Local (x, z) -> box offset (measured: floors of the 12 jungle temples, draw order per `O`).
pub(super) fn to_box(o: u8, x: i32, z: i32, d: i32) -> (i32, i32) {
    match o {
        0 => (x, z),
        2 => (x, d - 1 - z),
        3 => (z, x),
        _ => (d - 1 - z, x),
    }
}

/// The state transform that goes with [`to_box`].
pub(super) fn box_state(o: u8, s: u16) -> u16 {
    match o {
        0 => s,
        2 => transform_state(s, Rotation::Cw180, true),
        3 => transform_state(s, Rotation::Ccw90, true),
        _ => transform_state(s, Rotation::Cw90, false),
    }
}

/// Desert pyramid / jungle temple start (measured): orientation `nextInt(4)` over (north, east,
/// south, west) -> vanilla `O` (2, 3, 0, 1) like the swamp hut; box at the chunk corner, 21 x 21 x 15
/// / 12 x 15 x 10 (x and z swapped for `O` 1 and 3). Floor y: desert = minimum WORLD_SURFACE_WG over
/// the footprint (9/9 saved `HPos`; 3 of the 9 vanilla boxes then sit 1-2 lower, cause not found),
/// jungle = floor(mean WORLD_SURFACE_WG over the footprint) here, re-taken at placement time from
/// MOTION_BLOCKING_NO_LEAVES (see [`place_temple`]).
pub fn temple(g: &Generator, jungle_kind: bool, cx: i32, cz: i32, r: &mut JavaRandom) -> Piece {
    let o = [2u8, 3, 0, 1][r.next_int_bounded(4) as usize];
    let (w, d, h) = if jungle_kind {
        (12, 15, 10)
    } else {
        (21, 21, 15)
    };
    let (bx, bz) = box_size(o, w, d);
    let (x0, z0) = (cx * 16, cz * 16);
    let mut min = i32::MAX;
    let mut sum = 0i64;
    for x in 0..bx {
        for z in 0..bz {
            let hgt = g.first_free(x0 + x, z0 + z, false);
            min = min.min(hgt);
            sum += hgt as i64;
        }
    }
    let y = if jungle_kind {
        sum.div_euclid((bx * bz) as i64) as i32
    } else {
        min
    };
    Piece {
        bb: BBox::new([x0, y, z0], [x0 + bx - 1, y + h - 1, z0 + bz - 1]),
        kind: PieceKind::Temple {
            jungle: jungle_kind,
            origin: [x0, y, z0],
            o,
        },
    }
}

/// Place the part of a temple inside `clip`. Random cobblestone: vanilla draws `nextFloat()` from
/// the placement random for every cell of its random boxes in fill order (y, x, z; interior cells
/// that later become air draw too), then for single cells; `< 0.4` = cobblestone, else mossy.
/// Fitted on the 12 jungle temples: every cell's draw index is consistent with all of them.
pub fn place_temple(
    reg: &mut Region,
    clip: BBox,
    jungle_kind: bool,
    origin: [i32; 3],
    o: u8,
    r: &mut crate::features::R,
) {
    let l = if jungle_kind { jungle() } else { desert() };
    let mut origin = origin;
    // Jungle temple floor: floor(mean MOTION_BLOCKING_NO_LEAVES) over the box at placement time
    // (11/12 vanilla temples; the WG heightmap at the start gives 10/12, WORLD_SURFACE 4/12).
    // BASALT_TEMPLE_HM=ws|mb|mbnl|of|wg overrides the heightmap (measuring; desert = minimum).
    let hm = std::env::var("BASALT_TEMPLE_HM")
        .ok()
        .or_else(|| jungle_kind.then(|| "mbnl".to_string()));
    if let Some(hm) = hm {
        let kind = match hm.as_str() {
            "ws" => crate::region::Hm::WorldSurface,
            "mb" => crate::region::Hm::MotionBlocking,
            "mbnl" => crate::region::Hm::MotionBlockingNoLeaves,
            "of" => crate::region::Hm::OceanFloor,
            _ => crate::region::Hm::WorldSurfaceWg,
        };
        let (bx, bz) = box_size(o, l.w, l.d);
        let (mut sum, mut min) = (0i64, i32::MAX);
        for x in 0..bx {
            for z in 0..bz {
                let h = reg.height(kind, origin[0] + x, origin[2] + z);
                sum += h as i64;
                min = min.min(h);
            }
        }
        origin[1] = if jungle_kind {
            sum.div_euclid((bx * bz) as i64) as i32
        } else {
            min
        };
    }
    let cobble = BlockState::parse("cobblestone")
        .map(|b| b.0 as u16)
        .unwrap_or(0);
    let mossy = BlockState::parse("mossy_cobblestone")
        .map(|b| b.0 as u16)
        .unwrap_or(0);
    let f: Vec<f32> = (0..l.draws).map(|_| r.next_float()).collect();
    for (i, &(x, y, z, s)) in l.cells.iter().enumerate() {
        let st = if s == RANDOM {
            if f[l.draw[i] as usize] < 0.4 {
                cobble
            } else {
                mossy
            }
        } else {
            box_state(o, s)
        };
        let (bx, bz) = to_box(o, x, z, l.d);
        let p = [origin[0] + bx, origin[1] + y, origin[2] + bz];
        if clip.contains(p) {
            reg.set(p[0], p[1], p[2], st);
        }
    }
}

